*{box-sizing:border-box} :root{--bg:#101114;--panel:#181a1f;--panel2:#202228;--line:#303139;--muted:#92939a;--cream:#f2eee4;--red:#f04a37;--orange:#ff8a45;--green:#b8d647;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--cream);font-family:var(--sans)}body{min-height:100vh;background-image:radial-gradient(ellipse at 80% 6%,#272020 0,transparent 30%),linear-gradient(90deg,transparent 49.9%,#ffffff04 50%,transparent 50.1%);background-size:auto,64px 64px}.app{max-width:1440px;margin:auto;padding:0 6.2%;min-height:100vh;display:flex;flex-direction:column}.topbar{height:74px;border-bottom:1px solid #ffffff16;display:flex;align-items:center;justify-content:space-between;font-family:var(--mono);font-size:10px;letter-spacing:.12em}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--cream);font:700 14px var(--sans);letter-spacing:.08em}.brand-mark{background:var(--red);color:white;width:27px;height:27px;display:grid;place-items:center;font-size:16px;clip-path:polygon(0 0,100% 0,100% 74%,73% 100%,0 100%)}.brand-accent{color:var(--red)}.top-meta{color:#93939a;display:flex;align-items:center;gap:9px}.live-dot{height:6px;width:6px;border-radius:50%;background:#c1df49;box-shadow:0 0 8px #c1df49}.divider{color:#555}.sound-toggle{border:0;background:none;color:#b1b1b5;font:10px var(--mono);letter-spacing:.1em;cursor:pointer}.sound-toggle span{margin-left:7px}.screen{position:relative}.menu-screen{display:grid;grid-template-columns:1fr .95fr;column-gap:5%;padding:55px 0 0;flex:1}.menu-copy{position:relative;z-index:1}.eyebrow{font:10px var(--mono);letter-spacing:.14em;color:#a6a6aa}.eyebrow span{color:var(--red)}h1{font-size:clamp(54px,7vw,91px);line-height:.77;letter-spacing:-.08em;margin:28px 0 22px;font-weight:700}h1 span:not(.title-dot){color:var(--red)}.title-dot{color:var(--orange)}.intro{color:#a7a5a4;font-size:13px;line-height:1.75;margin-bottom:27px}.menu-options{max-width:450px}.option-label,.settings-row label{font:9px var(--mono);letter-spacing:.13em;color:#aaa}.segmented{display:flex;gap:5px;margin-top:8px}.segmented button{background:#1b1c21;color:#89898e;border:1px solid #33343a;padding:10px 13px;font:9px var(--mono);letter-spacing:.1em;cursor:pointer}.segmented button.selected{border-color:var(--red);color:#fff;background:#301c1c}.settings-row{display:flex;gap:20px;margin:17px 0 18px}.settings-row label{display:flex;flex-direction:column;gap:8px;flex:1}.settings-row select{background:#1b1c21;border:1px solid #37383d;color:#e5e1d8;padding:10px 11px;font:10px var(--mono);letter-spacing:.06em;outline:none}.start-button{width:100%;height:48px;background:var(--red);border:0;display:flex;justify-content:space-between;align-items:center;padding:0 16px;color:white;font:700 11px var(--mono);letter-spacing:.15em;cursor:pointer;transition:background .15s,transform .15s}.start-button:hover{background:#ff614c;transform:translateY(-2px)}.start-button b{font:22px var(--sans)}.key-hint{margin-top:13px;font:8px var(--mono);color:#77787e;letter-spacing:.05em}.key-hint span{color:#c3c0b9}.key-hint i{font-style:normal;color:var(--red);padding:0 3px}.menu-art{height:365px;align-self:start;position:relative;overflow:hidden;background:linear-gradient(155deg,#37201f,#1c1b20 62%,#211c1d);border:1px solid #ffffff15;margin-top:9px}.menu-art:before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent 49%,#ffffff0a 50%,transparent 51%),linear-gradient(0deg,transparent 49%,#ffffff0a 50%,transparent 51%);background-size:22px 22px;opacity:.5}.sun-disc{position:absolute;background:#ed4b37;width:180px;height:180px;border-radius:50%;top:36px;left:50%;transform:translateX(-50%);opacity:.83;box-shadow:0 0 48px #f04a3733}.menu-art canvas{position:absolute;height:90%;width:auto;image-rendering:pixelated;bottom:-7%;left:50%;transform:translateX(-50%);filter:drop-shadow(12px 4px 0 #111)}.art-label,.art-stamp{position:absolute;font:9px var(--mono);letter-spacing:.12em;line-height:1.6;color:#ddd}.art-label{top:15px;left:16px}.art-stamp{right:14px;bottom:14px;text-align:right;color:#f07962}.menu-scanline{position:absolute;inset:0;pointer-events:none;background:repeating-linear-gradient(0deg,transparent 0 3px,#00000014 4px)}.character-pick{grid-column:1/3;border-top:1px solid #ffffff20;margin-top:27px;padding-top:20px}.pick-header{display:flex;justify-content:space-between;align-items:flex-end}.pick-header h2{font-size:18px;letter-spacing:-.04em;margin:5px 0 13px}.pick-header h2 span{font:10px var(--mono);color:var(--red);vertical-align:middle;margin-left:4px}.pick-arrows{display:flex;gap:5px;margin-bottom:12px}.pick-arrows button{height:27px;width:31px;border:1px solid #383940;background:#1a1b20;color:#ddd;cursor:pointer}.fighter-grid{display:grid;grid-template-columns:repeat(10,1fr);gap:7px}.fighter-card{height:75px;border:1px solid #34353a;background:#1a1b1f;position:relative;cursor:pointer;overflow:hidden;transition:.15s}.fighter-card:hover{border-color:#9c4e42;background:#242126}.fighter-card.active{border-color:var(--red);background:#352020}.fighter-card canvas{width:100%;height:51px;image-rendering:pixelated;display:block}.fighter-card span{display:block;font:8px var(--mono);text-align:center;color:#bbb;letter-spacing:.06em;padding-top:2px}.fighter-card.active span{color:#fff}.fighter-card:after{content:'';position:absolute;width:4px;height:4px;background:var(--red);right:4px;top:4px;opacity:0}.fighter-card.active:after{opacity:1}.selected-info{margin-top:12px;background:#1a1b20;border:1px solid #2d2e34;min-height:74px;display:flex;align-items:center;padding:9px 13px;gap:13px}.fighter-portrait{height:51px;width:51px;background:#282127;border:1px solid #484047}.fighter-portrait canvas{width:100%;height:100%;image-rendering:pixelated}.fighter-copy{flex:1}.fighter-copy .eyebrow{font-size:8px}.fighter-copy h3{margin:3px 0 1px;font-size:14px;letter-spacing:.06em}.fighter-copy p{font-size:10px;color:#97969a;margin:0}.fighter-stats{display:flex;gap:13px}.stat{font:8px var(--mono);color:#8f9095}.stat b{display:block;color:#eee;font-size:10px;margin-bottom:4px}.stat-bar{height:3px;width:47px;background:#3b3b40;margin-top:4px}.stat-bar i{display:block;height:100%;background:var(--red)}.menu-footer{grid-column:1/3;display:flex;justify-content:space-between;color:#66676d;font:8px var(--mono);letter-spacing:.12em;padding:19px 0 15px}.menu-footer b{color:var(--red);font-size:12px;margin-left:5px}.hidden{display:none!important}
.game-screen{padding:15px 0 20px;flex:1}.game-top{height:36px;display:flex;align-items:center;justify-content:space-between;font:9px var(--mono);letter-spacing:.1em;color:#919197}.back-button,.pause-button{background:none;border:0;color:#ddd;font:10px var(--mono);cursor:pointer}.back-button span{margin-left:6px}.round-label b{color:var(--red)}.arena-name{color:#bbb}.battle-hud{height:61px;display:flex;align-items:center;gap:15px}.hud-fighter{flex:1}.hud-name{display:flex;justify-content:space-between;align-items:center;margin-bottom:5px;font:9px var(--mono);letter-spacing:.08em}.hud-name b{font-size:12px;color:#f4f0e7}.hud-name span{font-size:8px;color:#8d8d93}.right-hud .hud-name{flex-direction:row-reverse}.health-track{height:11px;background:#353238;padding:2px;clip-path:polygon(0 0,100% 0,98% 100%,0 100%)}.right-hud .health-track{transform:scaleX(-1)}.health-fill{height:100%;width:100%;background:linear-gradient(90deg,#f65c47,#f1a24d);transition:width .2s}.right-hud .health-fill{background:linear-gradient(90deg,#b3d844,#6ebc6d)}.meter-track{height:3px;background:#2c2d33;margin-top:4px}.meter-fill{height:100%;width:0;background:#e4c15c;transition:width .2s}.right-hud .meter-fill{margin-left:auto;background:#a5d850}.timer{width:52px;height:49px;display:flex;flex-direction:column;align-items:center;justify-content:center;border:1px solid #494349;background:#1b1b20;transform:skew(-5deg)}.timer span{font:700 23px var(--mono);line-height:1}.timer small{font:7px var(--mono);color:#9e9da2;margin-top:2px}.canvas-wrap{position:relative;width:100%;border:1px solid #434047;background:#19191d;overflow:hidden}.canvas-wrap canvas{width:100%;height:auto;aspect-ratio:16/9;display:block;image-rendering:pixelated}.canvas-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,#100e1266,transparent 14%,transparent 86%,#100e1266),linear-gradient(0deg,#100e1266,transparent 30%)}.fight-banner{position:absolute;top:35%;left:50%;transform:translate(-50%,-50%) skew(-7deg);color:#fff;font:700 clamp(25px,6vw,58px) var(--sans);letter-spacing:.12em;text-shadow:4px 4px #b3342e,0 0 20px #fb503c;z-index:2;pointer-events:none;transition:opacity .2s}.game-bottom{height:42px;display:flex;justify-content:space-between;align-items:center}.control-legend{display:flex;gap:14px;font:8px var(--mono);color:#94949a;letter-spacing:.07em}.control-legend span{display:flex;align-items:center;gap:3px}.control-legend kbd{font:8px var(--mono);border:1px solid #45454c;background:#202126;padding:3px 4px;color:#e4e0d9}.combo-readout{font:10px var(--mono);color:#f8bf5c;letter-spacing:.1em}.pause-button{color:#aaa;font-size:9px}.pause-button span{margin-left:4px}.touch-controls{display:none;justify-content:space-between;align-items:center;padding:3px 0 0}.touch-controls button{border:1px solid #58535a;background:#25242b;color:#eee;border-radius:5px;min-width:42px;height:38px;font:10px var(--mono);touch-action:none}.touch-move,.touch-actions{display:flex;gap:7px}.touch-actions button{min-width:46px}.touch-actions .ultimate-touch{background:#712d2a;border-color:#a34a3d}.result-overlay,.pause-overlay{position:absolute;inset:50px 0 0;z-index:4;background:#0d0d0ed9;display:grid;place-items:center}.result-card,.pause-card{width:min(410px,90%);text-align:center;border:1px solid #4a3c3b;background:#1a191e;padding:30px 25px;box-shadow:0 10px 50px #0009}.result-kicker{font:9px var(--mono);letter-spacing:.15em;color:#999}.result-ko{font:700 67px var(--sans);letter-spacing:-.08em;color:var(--red);line-height:1;margin:15px 0 5px;text-shadow:4px 4px #551f24}.winner-name{font:700 18px var(--mono);letter-spacing:.09em}.result-card p{color:#999;font-size:12px}.result-actions{display:flex;gap:8px;margin-top:22px}.result-actions button,.pause-card button{flex:1;padding:12px 7px;background:var(--red);border:0;color:white;font:9px var(--mono);letter-spacing:.06em;cursor:pointer}.result-actions button+button{background:#303037}.pause-card h2{font-size:24px;letter-spacing:-.04em}.pause-card button{width:100%;margin-top:9px}.pause-card button+button{background:#303037}.pause-card .eyebrow{color:var(--red)}
@media(max-width:850px){.app{padding:0 4%}.menu-screen{grid-template-columns:1fr .7fr;column-gap:3%;padding-top:36px}.menu-art{height:345px}.fighter-grid{grid-template-columns:repeat(5,1fr)}.fighter-card{height:66px}.fighter-card canvas{height:43px}.character-pick{margin-top:20px}.menu-footer{padding-bottom:10px}.control-legend{gap:7px}.control-legend span{gap:2px}}
@media(max-width:600px){.app{padding:0 15px}.topbar{height:55px}.top-meta{display:none}.brand{font-size:12px}.menu-screen{display:flex;flex-direction:column;padding-top:28px}.menu-copy{order:1}.menu-art{position:absolute;right:0;top:22px;height:205px;width:42%;opacity:.68;margin:0;border:0;background:transparent}.menu-art:before,.sun-disc,.art-label,.art-stamp,.menu-scanline{display:none}.menu-art canvas{height:100%;right:0;left:auto;transform:none;bottom:-3%}.eyebrow{font-size:8px}h1{font-size:61px;margin:22px 0 14px}.intro{font-size:11px;max-width:230px;margin-bottom:17px}.menu-options{max-width:none}.settings-row{gap:9px;margin:12px 0}.settings-row select{padding:9px 5px;font-size:8px}.segmented button{padding:9px 10px;font-size:8px}.key-hint{font-size:7px}.character-pick{order:2;margin-top:25px;padding-top:15px}.pick-header h2{font-size:15px}.fighter-grid{grid-template-columns:repeat(5,1fr);gap:5px}.fighter-card{height:65px}.selected-info{margin-top:8px;padding:8px;gap:8px}.fighter-portrait{height:43px;width:43px;flex-shrink:0}.fighter-copy .eyebrow{font-size:7px}.fighter-copy h3{font-size:12px}.fighter-copy p{font-size:9px}.fighter-stats{gap:6px}.stat{font-size:7px}.stat-bar{width:29px}.menu-footer{order:3;font-size:6px;margin-top:3px}.game-screen{padding-top:7px}.game-top{height:27px}.battle-hud{height:51px;gap:7px}.hud-name{font-size:8px}.hud-name b{font-size:10px}.hud-name span{font-size:6px}.timer{width:41px;height:41px}.timer span{font-size:20px}.canvas-wrap canvas{aspect-ratio:4/3}.control-legend{display:none}.game-bottom{height:36px}.touch-controls{display:flex}.game-screen:has(.touch-controls){padding-bottom:10px}.result-overlay,.pause-overlay{inset:30px 0 0}.result-card{padding:23px 16px}.result-actions{flex-direction:column}.pause-button{font-size:8px}}

(() => {
'use strict';
const roster = [
 {name:'DENJI',role:'CHAINSAW HYBRID',desc:'A reckless kid with a chainsaw for a heart.',colors:['#e8c28c','#d9412f','#283b39','#b9322d'],weapon:'#d94b37',stats:[4,5,4]},
 {name:'POWER',role:'BLOOD FIEND',desc:'The mighty Power bows to absolutely nobody.',colors:['#f2d5a5','#dfc8a9','#df493f','#bd343c'],weapon:'#cf3442',stats:[4,4,5]},
 {name:'AKI',role:'PUBLIC SAFETY HUNTER',desc:'A quiet hunter with a contract to keep.',colors:['#e6bb91','#13151b','#253e4a','#20232c'],weapon:'#6f9ca7',stats:[4,4,4]},
 {name:'MAKIMA',role:'CONTROL DEVIL',desc:'A smile that makes the whole room go still.',colors:['#f0c995','#e47845','#dfd8ca','#b92f32'],weapon:'#dc6b46',stats:[3,5,5]},
 {name:'KOBENI',role:'DEVIL HUNTER',desc:'Terrified, fast, and somehow still standing.',colors:['#ebc8a4','#302c32','#d9d4c8','#24252c'],weapon:'#d8d1c5',stats:[5,3,3]},
 {name:'HIMENO',role:'GHOST DEVIL CONTRACT',desc:'A veteran hunter with an unseen ally.',colors:['#e7c2a0','#1b1b20','#d3cfc5','#1e2025'],weapon:'#9a9eae',stats:[3,4,4]},
 {name:'BEAM',role:'SHARK FIEND',desc:'The loyal shark fiend is ready to dive in.',colors:['#d09d80','#428eb0','#e6e1d2','#346782'],weapon:'#52b6c5',stats:[5,4,3]},
 {name:'REZE',role:'BOMB DEVIL HYBRID',desc:'Sweet smile, explosive first impression.',colors:['#f0c7a2','#433348','#e6dfd1','#8b556c'],weapon:'#ed8e63',stats:[4,5,4]},
 {name:'KATANA MAN',role:'SAMURAI SWORD',desc:'A grudge sharpened into a blade.',colors:['#e6c095','#171a22','#4d5960','#c5c6bd'],weapon:'#a7bcc3',stats:[5,4,3]},
 {name:'QUANXI',role:'FIRST DEVIL HUNTER',desc:'The fastest hunter in any room she enters.',colors:['#ebcba8','#17181d','#d5d0c3','#393b45'],weapon:'#d2bfab',stats:[5,5,4]}
];
const arenas={
 tokyo:{name:'TOKYO STREETS',sky:'#27202a',far:'#443441',back:'#343038',ground:'#262328',accent:'#e54c3b',lights:'#f3c64b'},
 ruins:{name:'DEVIL RUINS',sky:'#24242b',far:'#504348',back:'#38353a',ground:'#27262a',accent:'#bf5940',lights:'#e8a94b'},
 office:{name:'PUBLIC SAFETY',sky:'#25282b',far:'#565250',back:'#3c3b3a',ground:'#292a2b',accent:'#d94c3e',lights:'#d9c999'},
 forest:{name:'DARK FOREST',sky:'#171f22',far:'#263c36',back:'#20332d',ground:'#1b2824',accent:'#9b4b42',lights:'#d99e55'}
};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const heroCanvas=$('#heroCanvas'), grid=$('#fighterGrid'), menu=$('#menuScreen'), gameScreen=$('#gameScreen'), canvas=$('#gameCanvas'), ctx=canvas.getContext('2d',{alpha:false});
ctx.imageSmoothingEnabled=false;
let selected=0,mode='ai',audioOn=true,audioCtx=null,game=null,lastTime=0,raf=0,keys={},touchKeys={},locked=false;
function makeSprite(c,pose='idle',frame=0,small=false){
 const w=small?64:64,h=small?64:80,cv=document.createElement('canvas');cv.width=w;cv.height=h;const g=cv.getContext('2d');g.imageSmoothingEnabled=false;
 const [skin,hair,coat,pants]=c.colors;const bob=(pose==='idle'?Math.floor(frame/22)%2:pose==='walk'||pose==='run'?Math.sin(frame*.7)*1.5:0)|0;
 let x=25,y=12+bob;const rect=(a,b,d,e,col)=>{g.fillStyle=col;g.fillRect(a,b,d,e)};
 // shadow and boots
 rect(12,65,41,4,'#101116');
 if(pose==='jump'){y-=7}
 if(pose==='knock'||pose==='down'){rect(12,54,34,8,pants);rect(6,61,24,5,coat);rect(35,58,18,5,pants);rect(21,51,13,5,skin);return cv}
 // legs, pose-dependent stride
 let stride=pose==='walk'||pose==='run'?Math.round(Math.sin(frame*.85)*(pose==='run'?5:3)):0;
 rect(25,43,9,20,pants);rect(38,42,9,21,pants);rect(25-stride,59,12,6,'#17171b');rect(38+stride,60,12,5,'#17171b');
 // body and neck
 rect(22,25,29,25,coat);rect(32,23,11,8,skin);rect(24,30,6,16,'#ffffff18');
 // face and hair
 rect(25,10,24,20,skin);rect(23,8,27,8,hair);rect(21,13,7,12,hair);rect(47,12,5,12,hair);rect(39,20,3,2,'#262226');rect(45,20,2,2,'#262226');
 // jacket / shirt detail
 rect(34,30,4,18,'#e7ded0');rect(35,32,2,2,'#cf4438');rect(23,32,4,15,coat);rect(47,32,5,14,coat);
 // individual silhouettes & signature gear
 if(c.name==='DENJI') {rect(20,8,5,17,'#d94b37');rect(18,6,7,4,'#d94b37');rect(47,9,6,16,'#d94b37');rect(48,6,7,4,'#d94b37');rect(27,29,18,4,'#b52e28');rect(28,36,3,5,'#222');}
 if(c.name==='POWER'){rect(20,7,6,14,hair);rect(47,8,5,13,hair);rect(22,4,5,5,'#e6ded2');rect(46,4,5,5,'#e6ded2');rect(30,34,6,7,'#f1e4dc');rect(39,35,5,6,'#f1e4dc');}
 if(c.name==='AKI'){rect(28,3,23,8,hair);rect(23,5,25,5,hair);rect(39,29,7,16,'#e5e0d4');rect(43,29,5,4,'#c64339');}
 if(c.name==='MAKIMA'){rect(28,4,22,6,hair);rect(27,7,4,18,hair);rect(48,8,4,17,hair);rect(29,20,17,3,'#b8443e');}
 if(c.name==='KOBENI'){rect(25,4,24,7,hair);rect(23,8,5,8,hair);rect(47,8,5,8,hair);rect(30,28,21,5,'#e2ddd2');}
 if(c.name==='HIMENO'){rect(24,3,29,8,hair);rect(24,9,5,16,hair);rect(47,9,6,15,hair);rect(32,18,3,3,'#17171b');}
 if(c.name==='BEAM'){rect(20,9,8,18,'#408ca7');rect(24,4,25,8,'#418fa8');rect(26,12,5,4,'#f1e5d6');rect(43,12,5,4,'#f1e5d6');rect(30,23,15,5,'#4eafbd');}
 if(c.name==='REZE'){rect(25,3,27,7,hair);rect(23,7,6,17,hair);rect(48,8,5,15,hair);rect(33,26,10,3,'#e6ded0');}
 if(c.name==='KATANA MAN'){rect(23,6,28,7,hair);rect(22,12,4,14,hair);rect(40,25,8,23,'#d4d2c8');rect(39,20,12,5,'#bbbcb9');}
 if(c.name==='QUANXI'){rect(25,3,28,7,hair);rect(23,7,6,17,hair);rect(47,8,5,13,hair);rect(30,19,3,3,'#eee');}
 // arms and attack silhouette
 const attack=['punch','kick','special','ultimate'].includes(pose),reach=pose==='ultimate'?22:pose==='special'?17:attack?12:0;
 if(attack){rect(45,31,reach,7,skin);rect(45+reach-2,30,6,9,coat);if(pose==='kick'){rect(43,44,reach+5,7,pants)}}else{rect(18,32,7,17,skin);rect(48,33,7,17,skin);}
 if(pose==='hurt'){rect(19,26,34,3,'#ef5a48')}
 if(pose==='victory'){rect(49,16,6,24,skin);rect(50,9,5,11,coat);}
 // ground pixel highlights
 rect(11,69,4,2,c.weapon);return cv;
}
function portraitTo(target,c,pose='idle'){const a=makeSprite(c,pose,0,true),g=target.getContext('2d');g.clearRect(0,0,target.width,target.height);g.imageSmoothingEnabled=false;g.drawImage(a,0,0,target.width,target.height)}
function renderRoster(){grid.innerHTML='';roster.forEach((c,i)=>{const card=document.createElement('button');card.className='fighter-card'+(i===selected?' active':'');card.setAttribute('aria-label',c.name);card.innerHTML=`<canvas width="64" height="50"></canvas><span>${c.name}</span>`;portraitTo(card.querySelector('canvas'),c);card.onclick=()=>selectFighter(i);grid.appendChild(card)});updateSelected();}
function updateSelected(){const c=roster[selected];$$('.fighter-card').forEach((el,i)=>el.classList.toggle('active',i===selected));$('#fighterName').textContent=c.name;$('#fighterRole').textContent=c.role;$('#fighterDesc').textContent=c.desc;const port=$('#fighterPortrait');port.innerHTML='<canvas width="64" height="64"></canvas>';portraitTo(port.firstChild,c);$('#fighterStats').innerHTML=['POWER','SPEED','SKILL'].map((n,i)=>`<div class="stat"><b>${n}</b>${['▰','▰','▰','▰','▰'].map((x,j)=>`<i style="color:${j<c.stats[i]?'#e65340':'#45454b'}">${x}</i>`).join('')}</div>`).join('')}
