function drawHero(){const g=heroCanvas.getContext('2d');g.clearRect(0,0,256,320);const s=makeSprite(roster[selected],'idle',performance.now()/80);g.imageSmoothingEnabled=false;g.drawImage(s,30,10,196,275)}
